pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _callee, bytes memory _data) public {
        // 1. Restrict callee to addresses with code: the fuzzer may generate code-free addresses
        //    where call() always succeeds, which would never trigger the difference.
        vm.assume(_callee.code.length > 0);
        // Ensure we aren't calling the test contract itself to avoid side effects
        vm.assume(_callee != address(this));
        vm.assume(_callee != address(c));

        // 2. Use a helper that always reverts to guarantee callee.call fails.
        //    Deploy it fresh per run.
        Reverter reverter = new Reverter();
        // Use the reverter's address as the callee in the forward call.
        bool reverted;
        try c.forward(address(reverter), _data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // 3. The reference C must revert when the external call fails.
        //    The buggy version does not revert, so reverted will be false for it.
        assertTrue(reverted, "forward must revert on failed sub-call");
    }
}

