import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, bytes calldata data) public {
        // Keep the sent Ether within a reasonable range and ensure we can fund it
        amount = bound(amount, 0, 100 ether);
        // Prepare the contract with some Ether
        vm.deal(address(c), amount);
        uint256 contractBalanceBefore = address(c).balance;
        // Try to forward the call with Ether attached; use try/catch to ignore reverts
        try c.forward{value: amount}(address(0), data) {} catch {}
        // The invariant: after any forward call, the balance of the contract never decreases
        // because the correct implementation sends Ether to the callee, not itself.
        // The bug makes the contract call itself, which never transfers Ether out,
        // so the balance should remain >= before for both versions, but actually
        // the bug makes forwarding with value increase the contract's balance by the same amount
        // (self-call with value), so the balance never goes below the original.
        // Wait: the bug replaces callee with address(this), so the call sends Ether back to itself,
        // so the contract's balance never changes. The reference sends Ether away, so balance decreases.
        // Therefore the invariant "balance >= contractBalanceBefore - amount" holds for both?
        // Let's think: reference sends `amount` to callee -> balance may decrease by amount if callee succeeds.
        // Bug sends `amount` to itself -> balance stays same.
        // The right invariant: the balance must be <= contractBalanceBefore, because sending Ether out reduces it.
        // Under the bug, the balance is exactly contractBalanceBefore (or more if someone else sends), but never less.
        // So: `address(c).balance <= contractBalanceBefore` holds for the reference (balance never increases),
        // but the bug can make it false when someone else sends? No, the invariant should always hold for reference.
        // Let's rederive: reference: send amount to callee -> balance = before - amount (if callee succeeds).
        // Bug: send amount to self -> balance unchanged.
        // So for reference, balance + amount <= before + amount? No.
        // A simple invariant: balance >= 0 (trivial).
        // We need something that the reference satisfies for ALL inputs and the bug breaks for some.
        // Reference: Ether leaves the contract -> balance monotonically non-increasing over the call (if call succeeds,
        // balance decreases by amount; if call fails, balance stays same). So balance <= oldBalance.
        // Bug: Ether stays inside -> balance is oldBalance (or higher if self-call somehow creates Ether? no).
        // So balance <= oldBalance is true for reference, and also true for bug? Bug balance = oldBalance, so it's also true.
        // We need a difference: Bug balance never changes, reference balance can change (decrease).
        // So an invariant could be: balance == oldBalance (false for reference when callee succeeds).
        // But reference doesn't guarantee that; it allows balance to decrease.
        // We need an invariant that ALWAYS holds for reference: "after forward, the balance is at most the previous balance"
        // holds for both. Not distinguishing.
        // What about: "the balance of the callee potentially increases"? We can't observe callee.
        // Let's read the contract's OWN balance change.
        // The difference: in reference, Ether goes OUT to an arbitrary address; in bug, Ether stays IN.
        // So the contract's balance after a successful forward in reference is <= initial - amount (if callee succeeds).
        // In bug, it's exactly initial.
        // So a property: "If the forward call does NOT revert, the contract's balance is strictly less than the initial balance"?
        // That's not universally true for reference because if amount=0, balance unchanged.
        // But we can add: if amount > 0 and the call succeeds, balance < initial.
        // We can observe success via try/catch.
        // Let's assert: (ok && amount > 0) implies address(c).balance < contractBalanceBefore.
        // For reference: true. For bug: false because balance unchanged.
        // However, the callee might be a contract that reverts, making the forward revert. So we must handle that.
        // We'll wrap in try/catch, get ok.
        uint256 contractBalanceAfter = address(c).balance;
        bool ok;
        try c.forward{value: amount}(address(this), data) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }
        // Now, after the external call, re-evaluate balance (the try/catch consumed no extra Ether)
        contractBalanceAfter = address(c).balance;
        // If the call succeeded and we sent positive Ether, the balance must have decreased
        // because in the reference, Ether is sent to the callee (address(this)), so it leaves the contract.
        // In the bug, the call goes to address(this), so the Ether stays inside, and balance remains same.
        assertTrue((ok && amount > 0) ? contractBalanceAfter < contractBalanceBefore : true);
    }
}
