        vm.assume(amount > 0);
        // Adversarial callee that accepts Ether
        Receiver receiver = new Receiver();
        bytes memory data = abi.encodeWithSignature("accept()");
        // Fund the test contract and then forward Ether to C
        vm.deal(address(this), amount);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "funding failed");
        uint256 balBefore = address(c).balance;
        // Call forward, sending Ether to the receiver
        vm.prank(address(this));
        c.forward{value: amount}(address(receiver), data);
        uint256 balAfter = address(c).balance;
        // The correct contract transfers Ether to the callee, so its balance must decrease
        // The mutant calls address(this), so the balance stays the same
        assertTrue(balAfter < balBefore);
    }
}

