pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes calldata _data) public {
        // The buggy version calls itself instead of the callee, potentially corrupting its own code
        // by executing arbitrary bytecode as a delegatecall-like effect via the fallback.
        // The reference version calls an external callee, so its own code remains intact.
        // We use a helper that returns valid but non-empty data to avoid revert on success.

        // Deploy a helper that will succeed and return data
        SuccessReturner helper = new SuccessReturner();

        // Ensure _data is non-empty and does not start with a known function selector to avoid
        // interfering with helper's logic; the fallback will handle it and succeed.
        vm.assume(_data.length > 0);

        // Record the contract's codehash before the call
        bytes32 codehashBefore;
        address cAddr = address(c);
        assembly {
            codehashBefore := extcodehash(cAddr)
        }

        // Call forward with the helper as callee
        c.forward(address(helper), _data);

        // Check that the contract's codehash is unchanged (reference property)
        bytes32 codehashAfter;
        assembly {
            codehashAfter := extcodehash(cAddr)
        }
        assertEq(codehashBefore, codehashAfter, "Contract codehash should not change");
    }
}

contract SuccessReturner {
    fallback() external payable returns (bytes memory) {
        assembly {
            // Return some data so the call succeeds and returns non-empty bytes
            mstore(0, 0x42)
            return(0, 32)
        }
    }
}

